SELECT 
  FROM apr17_corp_doc a
 WHERE a.apr17_reg_date BETWEEN #{startDate} AND #{closeDate}
   AND a.apr17_company_id = #{companyId}
 ORDER BY a.apr17_reg_date DESC

SELECT 
  FROM apr17_corp_doc a
 WHERE a.apr17_call_date BETWEEN #{startDate} AND #{closeDate}
   AND a.apr17_company_id = #{companyId}
   AND a.apr17_call_emp_id = #{personId}
   AND UPPER(CONCAT(a.apr17_provide_co, a.apr17_purpose)) LIKE UPPER(#{searchText})

   AND a.apr17_reg_date IS NULL

 ORDER BY a.apr17_call_date DESC

SELECT 
  FROM apr17_corp_doc a
 WHERE a.apr17_corp_doc_id = #{corpDocId}
   AND a.apr17_company_id  = #{companyId}

