   SET apr17_reg_date             = #{req.regDate}
     , apr17_stamp_cert_issue_cnt = #{req.stampCertIssueCnt}
     , apr17_stamp_cert_call_cnt  = #{req.stampCertCallCnt}
     , apr17_stamp_cert_use_cnt   = #{req.stampCertUseCnt}
     , apr17_corp_reg_issue_cnt   = #{req.corpRegIssueCnt}
     , apr17_corp_reg_call_cnt    = #{req.corpRegCallCnt}
     , apr17_corp_reg_use_cnt     = #{req.corpRegUseCnt}
     , apr17_provide_co           = #{req.provideCo}
     , apr17_purpose              = #{req.purpose}
     , apr17_requester            = #{req.requester}
     , apr17_note                 = #{req.note}
 WHERE apr17_corp_doc_id = #{req.corpDocId}
   AND apr17_company_id  = #{companyId}

