SELECT 
  FROM apr19_relate_stamp s
       INNER JOIN apr17_corp_doc a ON a.apr17_corp_doc_id = s.apr19_corp_doc_id
 WHERE s.apr19_corp_doc_id = #{corpDocId}
   AND a.apr17_company_id  = #{companyId}

SELECT 
  FROM apr19_relate_stamp s
       INNER JOIN apr17_corp_doc a ON a.apr17_corp_doc_id = s.apr19_corp_doc_id
 WHERE s.apr19_relate_stamp_id = #{relateStampId}
   AND a.apr17_company_id      = #{companyId}

mapper.update:
UPDATE apr19_relate_stamp
   SET apr19_stamp_id  = #{req.stampId}
     , apr19_stamp_cnt = #{req.stampCnt}
     , apr19_out_yn    = CASE WHEN COALESCE(#{req.outYn,jdbcType=BOOLEAN}, false) THEN 'true' ELSE 'false' END
 WHERE apr19_relate_stamp_id = #{req.relateStampId}
   AND apr19_corp_doc_id IN ( SELECT apr17_corp_doc_id FROM apr17_corp_doc WHERE apr17_company_id = #{companyId} )

mapper.insert:
INSERT INTO apr19_relate_stamp ( apr19_relate_stamp_id, apr19_corp_doc_id, apr19_stamp_id, apr19_stamp_cnt, apr19_out_yn )
SELECT #{req.relateStampId}, #{req.corpDocId}, #{req.stampId}, #{req.stampCnt}, CASE WHEN COALESCE(#{req.outYn,jdbcType=BOOLEAN}, false) THEN 'true' ELSE 'false' END
  FROM apr17_corp_doc
 WHERE apr17_corp_doc_id = #{req.corpDocId}
   AND apr17_company_id  = #{companyId}

